// Normalize Batch
// Stage is always dashboard_analysis in single-stage mode.
const input = $input.first().json;
const cases = Array.isArray(input.cases) ? input.cases : [];
const batchId = input.batchId || 'unknown';
const dashboardUuid = input.dashboardUuid || '';
const dashboardTitle = input.dashboardTitle || '';

if (cases.length === 0) {
  throw new Error('cases array is empty');
}
if (cases.length > 30) {
  throw new Error('cases exceed single batch limit of 30');
}

const normalizedCases = cases.map((item, index) => ({
  anomalyIndex: typeof item.anomalyIndex === 'number' ? item.anomalyIndex : index,
  dashboardUuid: item.dashboardUuid || dashboardUuid,
  dashboardTitle: item.dashboardTitle || dashboardTitle,
  metricName: item.metricName || item.cardTitle || '',
  ruleType: item.ruleType || '',
  messages: Array.isArray(item.messages) ? item.messages : [],
  evidence: item.evidence || {},
  sampleRows: Array.isArray(item.sampleRows) ? item.sampleRows : [],
  columns: Array.isArray(item.columns) ? item.columns : [],
}));

return [{
  json: {
    batchId,
    dashboardUuid,
    dashboardTitle,
    callbackUrl: input.callbackUrl || '',
    cases: normalizedCases,
  }
}];

// Build Batch Callback Payload
const input = $input.first().json;
const baseUrl = $getWorkflowStaticData('global').callbackBaseUrl;
const callbackUrl = input.callbackUrl || `${baseUrl.replace(/\/$/, '')}/api/metabase-anomaly-analysis/batch-callback`;

const difyCases = input.cases.map((c) => ({
  anomalyIndex: c.anomalyIndex,
  metricName: c.metricName,
  messages: c.messages,
  evidence: c.evidence,
  sampleRows: c.sampleRows.slice(0, 20),
  columns: c.columns,
}));

return [{
  json: {
    batchId: input.batchId,
    dashboardUuid: input.dashboardUuid,
    dashboardTitle: input.dashboardTitle,
    cases: difyCases,
    callbackUrl,
  }
}];

// Parse Dify response and extract verdicts
const input = $input.first().json;
const answer = input.answer || '{}';
let parsed = {};
try {
  parsed = JSON.parse(answer);
} catch (error) {
  // Try stripping markdown fences
  const cleaned = answer.replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, '');
  parsed = JSON.parse(cleaned);
}

const verdicts = Array.isArray(parsed.verdicts) ? parsed.verdicts : [];
const batchId = $('Build Batch Callback').item.json.batchId || input.batchId || 'unknown';

return [{
  json: {
    batchId,
    results: verdicts
  }
}];
